-- Deities and Demigods: D&D pantheon divine stat blocks, batch A.
-- Source: Deities and Demigods (2002), Chapter 3, pp. 58-66.
-- Printed 3.0 statistics are preserved, with official 3.5 revision deltas recorded separately in mechanics JSON.
-- Full deity blocks are stored as structured rules because the current schema has deity identity tables but no first-class divine stat-block table.

INSERT OR IGNORE INTO dnd35_sources
  (id,slug,name,abbreviation,publisher,system,edition,description,url,is_official,is_homebrew,owner_user_id)
VALUES ('dd-3.0','deities-and-demigods-3-0','Deities and Demigods','DD','Wizards of the Coast','dnd','3.0',
        'Deities and Demigods (2002): divine ranks, pantheons, salient divine abilities, divine minions, domains, spells, monsters, prestige classes, and ascension.',NULL,1,0,NULL);

UPDATE dnd35_deities SET symbol='Star above a milky nebula' WHERE source_id='dd-3.0' AND slug='bahamut' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Eye balanced on a pedestal inside a pentagon' WHERE source_id='dd-3.0' AND slug='boccob' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Silver crescent moon' WHERE source_id='dd-3.0' AND slug='corellon-larethian' AND owner_user_id IS NULL;
UPDATE dnd35_deities SET symbol='Rearing unicorn' WHERE source_id='dd-3.0' AND slug='ehlonna' AND owner_user_id IS NULL;

